"""Deciders must use the complete declaration evaluation protocol."""

import pytest

import factory


@pytest.mark.parametrize('choice', [False, True])
def test_faker_decider_defaults_and_branch_overrides(choice):
    class ChoiceFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'random_element', locale='en_US',
                elements=factory.LazyFunction(lambda: [choice]),
            ),
            yes_declaration=factory.Faker('random_element', elements=['yes']),
            no_declaration=factory.Faker('random_element', elements=['no']),
        )

    expected = 'yes' if choice else 'no'
    for _ in range(3):
        assert ChoiceFactory()['result'] == expected
        assert ChoiceFactory(result__elements=['override'])['result'] == 'override'


@pytest.mark.parametrize('choice', [False, True])
def test_wrapped_decider(choice):
    class ChoiceFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Transformer(choice, transform=lambda value: not value),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ChoiceFactory()['result'] == ('no' if choice else 'yes')
PY
